def list_matches(config: ConfigData, filter_tags: list[str], tag_filter_present: bool) -> list[tuple[str, ScriptEntry]]:
    aliases = sorted(config.scripts)
    if not tag_filter_present:
        return [(alias, config.scripts[alias]) for alias in aliases]
    matches: list[tuple[str, ScriptEntry]] = []
    for tag in filter_tags:
        for alias in aliases:
            entry = config.scripts[alias]
            if tag in entry.tags:
                matches.append((alias, entry))
    return matches


def table_output(rows: list[tuple[str, str, str, str]]) -> str:
    headers = ("Alias", "Tags", "Command", "Description")
    widths = [
        max(len(headers[0]), *(len(row[0]) for row in rows)),
        max(len(headers[1]), *(len(row[1]) for row in rows)),
        max(len(headers[2]), *(len(row[2]) for row in rows)),
        max(len(headers[3]), *(len(row[3]) for row in rows)),
    ]
    border = "≖" * (sum(widths) + 13)

    def format_row(values: tuple[str, str, str, str]) -> str:
        return (
            f"⋮ {values[0].ljust(widths[0])} "
            f"⋮ {values[1].ljust(widths[1])} "
            f"⋮ {values[2].ljust(widths[2])} "
            f"⋮ {values[3].ljust(widths[3])} ⋮"
        )

    lines = [border, format_row(headers), border]
    lines.extend(format_row(row) for row in rows)
    lines.append(border)
    return "\n".join(lines) + "\n"


def render_list(entries: list[tuple[str, ScriptEntry]], alias_only: bool, full: bool, cmd_width: int | None) -> str:
    if alias_only:
        return "".join(f"{alias}\n" for alias, _entry in entries)

    rows: list[tuple[str, str, str, str]] = []
    for alias, entry in entries:
        tags = ",".join(entry.tags)
        description = entry.description or ""
        lines = entry.command.splitlines() or [""]
        if full:
            for idx, command_line in enumerate(lines):
                rows.append(
                    (
                        alias if idx == 0 else "",
                        tags if idx == 0 else "",
                        command_line,
                        description if idx == 0 else "",
                    )
                )
        else:
            preview = lines[0]
            if cmd_width is not None:
                preview = preview[: max(cmd_width, 0)]
            rows.append((alias, tags, preview, description))

    if not rows:
        return ""
    return table_output(rows)


